PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',settings TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,topic TEXT REFERENCES entities(id),version INTEGER NOT NULL,content_version INTEGER NOT NULL,data TEXT NOT NULL,deleted_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS entities_owner ON entities(owner,kind,topic);
CREATE TABLE IF NOT EXISTS links(owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,source TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,field TEXT NOT NULL,target TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,PRIMARY KEY(source,field,target));
CREATE INDEX IF NOT EXISTS links_target ON links(target);
CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY,entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,version INTEGER NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analyses(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,topic TEXT REFERENCES entities(id),mode TEXT NOT NULL,snapshot TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestions(id TEXT PRIMARY KEY,analysis_id TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',target TEXT REFERENCES entities(id),feedback TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,state TEXT NOT NULL,created_at INTEGER NOT NULL,ended_at INTEGER,tokens INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE INDEX IF NOT EXISTS calls_owner_time ON calls(owner,created_at);
CREATE TABLE IF NOT EXISTS metrics(id INTEGER PRIMARY KEY,owner TEXT REFERENCES users(id) ON DELETE CASCADE,event TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,analysis_id TEXT REFERENCES analyses(id),rating TEXT NOT NULL,comment TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,window INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,snapshot TEXT NOT NULL,undone INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS errors(id INTEGER PRIMARY KEY,category TEXT NOT NULL,status INTEGER NOT NULL,duration INTEGER NOT NULL,created_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
